def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[4 if v == 4 else 0 for v in row] for row in grid]
    cols4 = [c for row in grid for c, v in enumerate(row) if v == 4]
    cols6 = [c for row in grid for c, v in enumerate(row) if v == 6]
    lo, hi = min(cols4), max(cols4)
    if max(cols6) < lo:
        axis2 = lo + max(cols6) + 1
    else:
        axis2 = hi + min(cols6) - 1
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 4:
                nc = axis2 - c
                if 0 <= nc < w:
                    out[r][nc] = 4
    return out
